import{makePath as l,pathStep as d,pathSolved as s}from"./boards/path.js";export function makeBoard(t,e){switch(t){case"path":return l(e)}}export function initialBoard(t){return{phase:"playing",values:Array(t.size*t.size).fill(""),selected:[],found:[],moves:0,mistakes:0,notice:""}}export function stepBoard(t,e,r){if(r.type==="reset")return initialBoard(t);if(e.phase!=="playing")return e;if(r.type==="reveal")return{...e,phase:"revealed",selected:t.solution,notice:""};if(r.type==="undo")return{...e,selected:e.selected.slice(0,-1),notice:""};if(r.type==="cell"){const o=d(t,e.selected,r.index);if(o===e.selected)return e;return{...e,selected:o,moves:e.moves+1,notice:"",phase:s(t,o)?"solved":"playing"}}return e}export function restoreBoard(t,e){const r=initialBoard(t);if(!e||typeof e!=="object")return r;const o=e;if(!Array.isArray(o.selected)||o.selected.length>t.size*t.size)return r;let n=r;for(const a of o.selected){if(typeof a!=="number")return r;const i=stepBoard(t,n,{type:"cell",index:a});if(i===n)return r;n=i}if(o.phase==="revealed")n=stepBoard(t,r,{type:"reveal"});return n}